package com.suyu.secexample.rce.controller;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;

@Controller
public class rcecontroller {
   @RequestMapping({"/rce"})
   public String input() {
      return "rce/rce";
   }

   @PostMapping({"/rceoutput"})
   public String index(@RequestParam("command") String command, Model model) {
      if (command == "" | command == null) {
         command = "whoami";
      }

      Process p = null;
      String result = null;

      try {
         p = Runtime.getRuntime().exec(command);
      } catch (IOException e) {
         e.printStackTrace();
      }

      InputStream is = p.getInputStream();
      BufferedReader reader = new BufferedReader(new InputStreamReader(is));
      String s = null;

      while(true) {
         try {
            if ((s = reader.readLine()) == null) {
               break;
            }
         } catch (IOException e) {
            e.printStackTrace();
         }

         result = s;
      }

      model.addAttribute("result", result);
      return "rce/rceoutput";
   }
}

package com.suyu.secexample.fastjson.controller;

import com.alibaba.fastjson.JSON;
import com.alibaba.fastjson.JSONObject;
import com.suyu.secexample.fastjson.model.User;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;

@Controller
public class fastjsoncontroller {
   User user = new User();

   @GetMapping({"/fastjson"})
   public String input() {
      return "fastjson/fastjson";
   }

   @RequestMapping({"fastjson"})
   public String fastjson1(@RequestBody String jsonData, Model model) {
      JSONObject jsonObject = JSON.parseObject(jsonData);
      this.user.setAge(jsonObject.get("age").toString());
      this.user.setUsername(jsonObject.get("username").toString());
      model.addAttribute("result", this.user);
      return "fastjson/fastjsonoutput";
   }

   @RequestMapping({"fastjson2"})
   public String fastjson2(Model model) {
      model.addAttribute("result", this.user);
      return "fastjson/fastjsonoutput";
   }
}

package com.suyu.secexample.spel.controller;

import org.springframework.expression.Expression;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestParam;

@Controller
public class Spelcontroller {
   @GetMapping({"/spel"})
   public String input() {
      return "spel/spel";
   }

   @PostMapping({"/speloutput"})
   public String index(@RequestParam("selector") String selector, Model model) {
      if (selector == "" | selector == null) {
         selector = String.valueOf(666);
      }

      Expression expression = (new SpelExpressionParser()).parseExpression(selector);
      expression.getValue();
      model.addAttribute("selector", selector);
      return "spel/speloutput";
   }
}

